// client/src/pages/Roulette.jsx (수정)

import React, { useState, useEffect, useRef } from 'react';
import { toast } from 'react-toastify';
import { useAuth } from '../hooks/useAuth'; 
import RouletteWheel from '../components/RouletteWheel'; 


// 💡 보조 함수: 룰렛 휠의 최종 각도를 계산하는 로직
const calculateTargetRotation = (rewards, targetRewardName) => {
    const segmentsCount = rewards.length;
    if (segmentsCount === 0) return 0;

    // 1. 목표 세그먼트 인덱스 찾기
    const targetIndex = rewards.findIndex(r => r.name === targetRewardName);
    if (targetIndex === -1) return 0; 
    
    // 2. 세그먼트의 각도 계산
    const segmentAngle = 360 / segmentsCount;
    
    // 3. 목표 세그먼트의 중앙 각도
    // 룰렛 휠은 시계 반대 방향으로 회전시키고, 포인터는 12시 방향(0도)에 있다고 가정합니다.
    // 회전 각도 = (총 바퀴 수 * 360) + (포인터 위치에 세그먼트를 맞추기 위한 각도)
    
    // 포인터(0도)에 목표 인덱스를 맞추기 위한 회전량:
    // (targetIndex * segmentAngle)은 목표 세그먼트의 시작 각도입니다.
    // 중앙에 맞추기 위해 segmentAngle/2 만큼 더 회전해야 합니다.
    const angleToTargetStart = targetIndex * segmentAngle;
    const angleToTargetCenter = angleToTargetStart + segmentAngle / 2;
    
    // 룰렛은 360도에서 시작하므로, 0도를 기준으로 반시계방향으로 회전해야 합니다.
    // 정지 각도 = 360 - angleToTargetCenter
    
    // 4. 회전 수 + 정지 각도
    const rotationTurns = 5; // 최소 5바퀴 회전
    const baseRotation = rotationTurns * 360; 
    
    // 5. 목표 인덱스가 0도 (포인터)에 오도록 맞추는 각도
    // 360 - angleToTargetCenter => 포인터 정 중앙에 오도록 맞춤
    const finalStopAngle = 360 - angleToTargetCenter;
    
    // 6. 무작위 오차 추가 (세그먼트 내에서 랜덤한 위치에 멈추게 함)
    const randomOffset = (Math.random() * (segmentAngle - 8)) - (segmentAngle/2 - 4);
    
    const totalRotation = baseRotation + finalStopAngle + randomOffset;
    
    return totalRotation;
};


function RoulettePage() {
    const { user, updateUserPoints } = useAuth(); 
    
    const [rewards, setRewards] = useState([]);
    const [isSpinning, setIsSpinning] = useState(false);
    const [spinCost] = useState(100); 
    const [rotationAngle, setRotationAngle] = useState(0);
    const [spinResult, setSpinResult] = useState(null);
    const containerRef = useRef(null);
    const [mousePos, setMousePos] = useState({ x: 50, y: 50 });
    
    // 미션 시스템
    const [missions, setMissions] = useState([
        { id: 1, title: '오늘 첫 방문', description: '오늘 처음으로 룰렛 페이지 방문', points: 5, completed: false, icon: '👋' },
        { id: 2, title: '리뷰 작성하기', description: '화장품 리뷰 1개 작성', points: 5, completed: false, icon: '✍️' },
        { id: 3, title: '좋아요 누르기', description: '다른 사람 리뷰에 좋아요 3개', points: 5, completed: false, icon: '❤️' },
        { id: 4, title: '친구 초대하기', description: '친구 1명 초대 성공', points: 5, completed: false, icon: '👥' },
        { id: 5, title: '프로필 완성', description: '프로필 정보 100% 완성', points: 5, completed: false, icon: '📝' },
    ]);

    // 첫 방문 미션 자동 완료
    useEffect(() => {
        const todayVisit = localStorage.getItem('roulette_visit_' + new Date().toDateString());
        if (!todayVisit) {
            localStorage.setItem('roulette_visit_' + new Date().toDateString(), 'true');
            setMissions(prev => prev.map(m => 
                m.id === 1 ? { ...m, completed: true } : m
            ));
            // 포인트 자동 지급
            if (user) {
                updateUserPoints((user.points || 0) + 5);
                toast.success('🎁 오늘 첫 방문 미션 완료! +5P');
            }
        } else {
            setMissions(prev => prev.map(m => 
                m.id === 1 ? { ...m, completed: true } : m
            ));
        }
    }, [user]);

    // 미션 완료 핸들러
    const completeMission = (missionId) => {
        const mission = missions.find(m => m.id === missionId);
        if (mission && !mission.completed && user) {
            setMissions(prev => prev.map(m => 
                m.id === missionId ? { ...m, completed: true } : m
            ));
            updateUserPoints((user.points || 0) + mission.points);
            toast.success(`🎁 미션 완료! +${mission.points}P`);
        }
    };

    // 마우스 추적 (배경 효과용)
    useEffect(() => {
        const handleMouseMove = (e) => {
            if (containerRef.current) {
                const rect = containerRef.current.getBoundingClientRect();
                setMousePos({
                    x: ((e.clientX - rect.left) / rect.width) * 100,
                    y: ((e.clientY - rect.top) / rect.height) * 100
                });
            }
        };
        window.addEventListener('mousemove', handleMouseMove);
        return () => window.removeEventListener('mousemove', handleMouseMove);
    }, []);

    // 비로그인 상태여도 룰렛 페이지는 볼 수 있도록 리다이렉트 제거
    // 스핀 동작은 버튼의 disabled 속성으로 제어합니다.

    useEffect(() => {
        // 화장품 브랜드 쿠폰 목록 (브랜드 홈페이지 URL 포함)
        const defaultRewards = [
            { name: '이니스프리 10% OFF', type: 'COUPON', probability: 8, brand: 'Innisfree', url: 'https://www.innisfree.com' },
            { name: '에뛰드 10% OFF', type: 'COUPON', probability: 8, brand: 'Etude', url: 'https://www.etude.com' },
            { name: '토니모리 10% OFF', type: 'COUPON', probability: 6, brand: 'TonyMoly', url: 'https://www.tonymoly.com' },
            { name: '미샤 10% OFF', type: 'COUPON', probability: 5, brand: 'Missha', url: 'https://www.missha.com' },
            { name: '클리오 10% OFF', type: 'COUPON', probability: 6, brand: 'Clio', url: 'https://www.cliocosmetic.com' },
            { name: '롬앤 10% OFF', type: 'COUPON', probability: 7, brand: "Rom&nd", url: 'https://romand.co.kr' },
            { name: '라네즈 10% OFF', type: 'COUPON', probability: 5, brand: 'Laneige', url: 'https://www.laneige.com' },
            { name: '올리브영 10% OFF', type: 'COUPON', probability: 7, brand: 'OliveYoung', url: 'https://www.oliveyoung.co.kr' },
            { name: '10 포인트', type: 'POINTS', probability: 10 },
            { name: '50 포인트', type: 'POINTS', probability: 8 },
            { name: '꽝', type: 'NONE', probability: 30 },
        ];
        setRewards(defaultRewards);
    }, []);


    // 룰렛 실행 핸들러
    const handleSpin = async () => {
        if (isSpinning || !user) return;
        
        if (user.points < spinCost) {
            toast.error(`포인트가 부족합니다. (필요: ${spinCost}P)`);
            return;
        }

        setIsSpinning(true);
        setSpinResult(null);

        try {
            // 클라이언트 전용 스핀: 가중치 기반 랜덤 선택
            const weightedPick = (items) => {
                const total = items.reduce((s, it) => s + (it.probability || 0), 0);
                const r = Math.random() * total;
                let acc = 0;
                for (const it of items) {
                    acc += (it.probability || 0);
                    if (r <= acc) return it;
                }
                return items[items.length - 1];
            };

            const chosen = weightedPick(rewards);

            // 포인트 계산: 보상 텍스트에서 숫자 추출 (예: '50 포인트')
            let addPoints = 0;
            if (chosen.type === 'POINTS') {
                const m = chosen.name.match(/(\d+)/);
                addPoints = m ? parseInt(m[1], 10) : 0;
            }

            const newPoints = (user ? user.points : 0) - spinCost + addPoints;

            const data = {
                success: true,
                reward: chosen,
                coupon: chosen.type === 'COUPON' ? { code: 'LOCAL-' + Math.random().toString(36).slice(2,9), discount: 10 } : null,
                userPoints: newPoints,
                message: chosen.type === 'COUPON' ? `${chosen.name} 쿠폰이 발급되었습니다.` : `${addPoints} 포인트를 획득했습니다!`,
            };

            // 2. 최종 멈출 각도 계산 (현재 각도에 더해줍니다)
            const targetRotation = calculateTargetRotation(rewards, data.reward.name);

            // 3. spinning 클래스를 제거하고 최종 각도로 추가 회전시켜 멈춤
            setIsSpinning(false);
            setRotationAngle(prev => prev + targetRotation);

            // 4. 애니메이션 종료 후 결과 표시 (4.2초)
            setTimeout(() => {
                setSpinResult(data); // 최종 결과 저장

                // 5. AuthContext의 사용자 포인트 업데이트
                updateUserPoints(newPoints);

                // 6. 보상 알림
                if (data.reward.type === 'COUPON') {
                    toast.success(`🎉 ${data.message} 쿠폰 코드: ${data.coupon.code}`);
                } else {
                    toast.info(data.message);
                }
            }, 4200);

        } catch (error) {
            setIsSpinning(false);
            setSpinResult({ success: false, message: '룰렛 실행 중 오류가 발생했습니다.' });
            toast.error('룰렛 실행 중 오류가 발생했습니다.');
        }
    };

    return (
        <div 
            ref={containerRef}
            style={{
                minHeight: '100vh',
                background: `
                    radial-gradient(circle at ${mousePos.x}% ${mousePos.y}%, rgba(168,85,247,0.12) 0%, transparent 50%),
                    linear-gradient(180deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%)
                `,
                padding: '40px 20px 80px',
                position: 'relative',
                overflow: 'hidden'
            }}
        >
            {/* CSS 애니메이션 */}
            <style>{`
                @keyframes float {
                    0%, 100% { transform: translateY(0px) rotate(0deg); }
                    50% { transform: translateY(-20px) rotate(10deg); }
                }
                @keyframes pulse {
                    0%, 100% { transform: scale(1); opacity: 0.6; }
                    50% { transform: scale(1.2); opacity: 1; }
                }
                @keyframes shimmer {
                    0% { background-position: -200% center; }
                    100% { background-position: 200% center; }
                }
                @keyframes glow {
                    0%, 100% { box-shadow: 0 0 30px rgba(168,85,247,0.4); }
                    50% { box-shadow: 0 0 60px rgba(168,85,247,0.7); }
                }
                @keyframes sparkle {
                    0%, 100% { opacity: 0; transform: scale(0); }
                    50% { opacity: 1; transform: scale(1); }
                }
                @keyframes slideUp {
                    from { opacity: 0; transform: translateY(30px); }
                    to { opacity: 1; transform: translateY(0); }
                }
                @keyframes bounce {
                    0%, 100% { transform: translateY(0); }
                    50% { transform: translateY(-10px); }
                }
                @keyframes spin {
                    from { transform: rotate(0deg); }
                    to { transform: rotate(360deg); }
                }
                .reward-card:hover {
                    transform: translateY(-8px) scale(1.02);
                    box-shadow: 0 20px 50px rgba(168,85,247,0.3);
                }
            `}</style>

            {/* 플로팅 장식 */}
            <div style={{ position: 'absolute', top: 80, left: '10%', fontSize: 40, animation: 'float 6s ease-in-out infinite', opacity: 0.5, pointerEvents: 'none' }}>🎰</div>
            <div style={{ position: 'absolute', top: 150, right: '15%', fontSize: 32, animation: 'float 5s ease-in-out infinite 1s', opacity: 0.4, pointerEvents: 'none' }}>✨</div>
            <div style={{ position: 'absolute', bottom: 200, left: '8%', fontSize: 28, animation: 'float 7s ease-in-out infinite 2s', opacity: 0.35, pointerEvents: 'none' }}>💎</div>
            <div style={{ position: 'absolute', bottom: 300, right: '12%', fontSize: 36, animation: 'float 4s ease-in-out infinite 0.5s', opacity: 0.45, pointerEvents: 'none' }}>🎡</div>
            <div style={{ position: 'absolute', top: '40%', left: '5%', fontSize: 24, animation: 'pulse 3s ease-in-out infinite', opacity: 0.3, pointerEvents: 'none' }}>⭐</div>
            <div style={{ position: 'absolute', top: '60%', right: '8%', fontSize: 20, animation: 'pulse 4s ease-in-out infinite 1s', opacity: 0.25, pointerEvents: 'none' }}>💫</div>

            <div style={{ maxWidth: 900, margin: '0 auto', position: 'relative', zIndex: 1 }}>
                {/* 헤더 - 프리미엄 */}
                <div style={{ textAlign: 'center', marginBottom: 40, animation: 'slideUp 0.6s ease-out' }}>
                    <h1 style={{ 
                        fontSize: 48, 
                        fontWeight: 900,
                        background: 'linear-gradient(135deg, #ffd700 0%, #ff8c00 25%, #ff4d88 50%, #a855f7 75%, #3b82f6 100%)',
                        backgroundSize: '200% auto',
                        WebkitBackgroundClip: 'text',
                        WebkitTextFillColor: 'transparent',
                        animation: 'shimmer 3s linear infinite',
                        marginBottom: 12,
                        textShadow: '0 0 60px rgba(255,215,0,0.3)'
                    }}>
                        🎰 행운의 룰렛
                    </h1>
                    <p style={{ 
                        color: 'rgba(255,255,255,0.7)', 
                        fontSize: 16,
                        fontWeight: 500
                    }}>
                        행운을 시험해보세요! 포인트와 특별 쿠폰이 기다립니다 ✨
                    </p>
                </div>
                
                {/* 포인트 정보 카드 - 프리미엄 */}
                <div style={{ 
                    background: 'linear-gradient(135deg, rgba(255,255,255,0.1) 0%, rgba(255,255,255,0.05) 100%)',
                    backdropFilter: 'blur(20px)',
                    borderRadius: 24,
                    padding: '28px 36px',
                    marginBottom: 40,
                    border: '1px solid rgba(255,255,255,0.2)',
                    boxShadow: '0 20px 60px rgba(0,0,0,0.3)',
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    animation: 'slideUp 0.6s ease-out 0.1s both'
                }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 16 }}>
                        <div style={{
                            width: 60,
                            height: 60,
                            borderRadius: '50%',
                            background: 'linear-gradient(135deg, #ffd700, #ff8c00)',
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            fontSize: 28,
                            boxShadow: '0 8px 24px rgba(255,215,0,0.4)',
                            animation: 'pulse 2s ease-in-out infinite'
                        }}>💰</div>
                        <div>
                            <div style={{ color: 'rgba(255,255,255,0.6)', fontSize: 13, fontWeight: 600, marginBottom: 4 }}>나의 포인트</div>
                            <div style={{ 
                                fontSize: 32, 
                                fontWeight: 900, 
                                color: '#ffd700',
                                textShadow: '0 0 20px rgba(255,215,0,0.5)'
                            }}>
                                {user ? user.points.toLocaleString() : 0} P
                            </div>
                        </div>
                    </div>
                    <div style={{
                        background: 'rgba(255,77,136,0.2)',
                        borderRadius: 16,
                        padding: '12px 20px',
                        border: '1px solid rgba(255,77,136,0.3)'
                    }}>
                        <div style={{ color: 'rgba(255,255,255,0.6)', fontSize: 12, marginBottom: 2 }}>1회 참여 비용</div>
                        <div style={{ color: '#ff4d88', fontSize: 20, fontWeight: 800 }}>{spinCost} P</div>
                    </div>
                </div>
                
                {/* 💡 RouletteWheel 컴포넌트에 필요한 props 전달 (중앙 버튼을 내부에 렌더링) */}
                <div style={{ 
                    display: 'flex', 
                    justifyContent: 'center', 
                    marginBottom: 40,
                    animation: 'slideUp 0.6s ease-out 0.2s both'
                }}>
                    <div style={{
                        background: 'radial-gradient(circle, rgba(168,85,247,0.2) 0%, transparent 70%)',
                        borderRadius: '50%',
                        padding: 40,
                        animation: isSpinning ? 'glow 0.5s ease-in-out infinite' : 'none'
                    }}>
                        <RouletteWheel 
                            rewards={rewards} 
                            isSpinning={isSpinning}
                            rotationAngle={rotationAngle} // 계산된 최종 각도 전달
                            spinResult={spinResult}
                            onSpin={handleSpin}
                            disabled={isSpinning || !user || (user && user.points < spinCost)}
                            spinCost={spinCost}
                        />
                    </div>
                </div>
                
                {/* 결과 표시 - 프리미엄 */}
                {spinResult && (
                    <div style={{
                        background: spinResult.success === false 
                            ? 'linear-gradient(135deg, rgba(239,68,68,0.2) 0%, rgba(239,68,68,0.1) 100%)'
                            : 'linear-gradient(135deg, rgba(255,215,0,0.2) 0%, rgba(168,85,247,0.2) 100%)',
                        backdropFilter: 'blur(20px)',
                        borderRadius: 24,
                        padding: '32px',
                        marginBottom: 40,
                        border: `1px solid ${spinResult.success === false ? 'rgba(239,68,68,0.3)' : 'rgba(255,215,0,0.3)'}`,
                        boxShadow: '0 20px 60px rgba(0,0,0,0.3)',
                        textAlign: 'center',
                        animation: 'slideUp 0.5s ease-out'
                    }}>
                        <div style={{ fontSize: 48, marginBottom: 16, animation: 'bounce 1s ease-in-out infinite' }}>
                            {spinResult.success ? '🎉' : '😢'}
                        </div>
                        <h4 style={{ 
                            fontSize: 24, 
                            fontWeight: 800, 
                            color: '#fff',
                            marginBottom: 12
                        }}>{spinResult.success ? '축하합니다!' : '오류 발생'}</h4>
                        <p style={{ color: 'rgba(255,255,255,0.8)', fontSize: 16, marginBottom: 16 }}>{spinResult.message}</p>
                        {spinResult.coupon && (
                            <div style={{
                                background: 'rgba(255,255,255,0.1)',
                                borderRadius: 16,
                                padding: '20px',
                                marginTop: 16
                            }}>
                                <div style={{ color: 'rgba(255,255,255,0.7)', fontSize: 13, marginBottom: 8 }}>🎫 쿠폰 코드</div>
                                <div style={{ 
                                    fontSize: 24, 
                                    fontWeight: 800, 
                                    color: '#3b82f6',
                                    fontFamily: 'monospace',
                                    letterSpacing: 2
                                }}>{spinResult.coupon.code}</div>
                                <div style={{ color: '#ffd700', fontSize: 18, fontWeight: 700, marginTop: 8 }}>
                                    {spinResult.coupon.discount}% 할인
                                </div>
                            </div>
                        )}
                    </div>
                )}

                {/* 보상 목록 - 프리미엄 */}
                <div style={{ animation: 'slideUp 0.6s ease-out 0.3s both' }}>
                    <h3 style={{ 
                        fontSize: 24, 
                        fontWeight: 800, 
                        color: '#fff',
                        marginBottom: 24,
                        display: 'flex',
                        alignItems: 'center',
                        gap: 12
                    }}>
                        <span style={{ animation: 'bounce 2s ease-in-out infinite' }}>🎯</span>
                        룰렛 보상 목록
                    </h3>
                    
                    <div style={{ 
                        display: 'grid', 
                        gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', 
                        gap: 16 
                    }}>
                        {rewards.length > 0 ? (
                            rewards.map((reward, index) => (
                                <div 
                                    key={index} 
                                    className="reward-card"
                                    style={{
                                        background: reward.type === 'COUPON' 
                                            ? 'linear-gradient(135deg, rgba(168,85,247,0.2) 0%, rgba(168,85,247,0.1) 100%)'
                                            : reward.type === 'NONE'
                                            ? 'linear-gradient(135deg, rgba(107,114,128,0.2) 0%, rgba(107,114,128,0.1) 100%)'
                                            : 'linear-gradient(135deg, rgba(255,215,0,0.2) 0%, rgba(255,215,0,0.1) 100%)',
                                        backdropFilter: 'blur(10px)',
                                        borderRadius: 20,
                                        padding: '24px',
                                        border: `1px solid ${
                                            reward.type === 'COUPON' ? 'rgba(168,85,247,0.3)' 
                                            : reward.type === 'NONE' ? 'rgba(107,114,128,0.3)'
                                            : 'rgba(255,215,0,0.3)'
                                        }`,
                                        transition: 'all 0.3s ease',
                                        animation: `slideUp 0.4s ease-out ${index * 0.05}s both`,
                                        textAlign: 'center'
                                    }}
                                >
                                    <div style={{ 
                                        fontSize: 32, 
                                        marginBottom: 12,
                                        animation: 'bounce 3s ease-in-out infinite',
                                        animationDelay: `${index * 0.2}s`
                                    }}>
                                        {reward.type === 'COUPON' ? '🎫' : reward.type === 'NONE' ? '💨' : '💰'}
                                    </div>
                                    <p style={{ 
                                        fontWeight: 700, 
                                        fontSize: 16, 
                                        color: '#fff',
                                        marginBottom: 8
                                    }}>{reward.name}</p>
                                    <p style={{ 
                                        fontSize: 14, 
                                        color: 'rgba(255,255,255,0.5)',
                                        fontWeight: 600
                                    }}>확률: {reward.probability}%</p>
                                </div>
                            ))
                        ) : (
                            <p style={{ 
                                gridColumn: 'span 3', 
                                textAlign: 'center', 
                                color: 'rgba(255,255,255,0.5)' 
                            }}>보상 목록을 불러오는 중...</p>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}

export default RoulettePage;
